99	  void ScheduleWithHint(std::function<void()> fn, int start, int end) override {
100	    return thread_pool().ScheduleWithHint(std::move(fn), start, end);
101	  }
102	
103	  void Cancel() override { thread_pool().Cancel(); }
104	
105	  int NumThreads() const override { return thread_pool().NumThreads(); }
106	
107	  int CurrentThreadId() const override {
108	    return thread_pool().CurrentThreadId();
109	  }
110	
111	 private:
