147	class TfrtSession : public tensorflow::Session {
148	 public:
149	  // Besides options, these arguments are passed from those stored in
150	  // `TfrtSessionfactory`.
151	  // `runtime` should be non-null, with lifetime exceeding that of TfrtSession.
152	  // A null `backend_compiler` indicates the default TFRT compiler will be used,
153	  // with existence consistent during the lifetime of TfrtSession.
154	  explicit TfrtSession(const SessionOptions& options,
155	                       tensorflow::tfrt_stub::Runtime* runtime,
156	                       TfrtDeviceInfraTarget device_target,
157	                       bool tpu_use_tpu_runner, bool use_gpu,
158	                       TfrtSessionInterOpThreadPools inter_op_thread_pools,
159	                       bool enable_mlrt, bool enable_async_native_lowering,
160	                       bool enable_tpu_host_allocator_for_inputs,
161	                       tensorflow::BackendCompiler* backend_compiler,
162	                       std::unique_ptr<StaticDeviceMgr> device_manager)
163	      : runtime_{runtime},
164	        device_target_{device_target},
165	        tpu_use_tpu_runner_{tpu_use_tpu_runner},
166	        use_gpu_{use_gpu},
167	        enable_tpu_host_allocator_for_inputs_(
168	            enable_tpu_host_allocator_for_inputs),
169	        inter_op_thread_pools_{std::move(inter_op_thread_pools)},
170	        enable_mlrt_(enable_mlrt),
171	        enable_async_native_lowering_(enable_async_native_lowering),
172	        options_{options},
173	        backend_compiler_(backend_compiler),
174	        device_manager_(std::move(device_manager)) {}
175	
176	  absl::Status Create(const GraphDef& graph) override {
177	    return Create(GraphDef(graph));
178	  }
179	
180	  absl::Status Create(GraphDef&& graph) override {
181	    absl::MutexLock lock(session_state_lock_);
182	    return CreateLocked(std::move(graph));
183	  }
184	
185	  absl::Status CreateLocked(GraphDef graph)
186	      TF_EXCLUSIVE_LOCKS_REQUIRED(session_state_lock_) {
187	    if (graph.node_size() == 0) {
188	      LOG(ERROR) << "Ignoring empty graph.";
189	      return absl::OkStatus();
190	    }
191	    if (session_state_ == SessionState::kCreated) {
192	      return absl::AlreadyExistsError(
193	          "A Graph has already been created for this session.");
194	    }
195	    TF_RETURN_IF_ERROR(CheckNotClosedLocked());
196	
197	    auto options = GetGraphExecutionOptions();
198	    tensorflow::tfrt_stub::UpdateTpuTargetByBridgeCompatibility(options, graph);
199	
200	    // Remove the ConfigureDistributedTPU node as it is placed on the TPU_SYSTEM
201	    // device which is not supported by the compiler.
202	    // TODO(188009822): Figure out a cleaner way to address this.
203	    auto* nodes = graph.mutable_node();
204	    for (auto it = nodes->begin(), end = nodes->end(); it != end; ++it) {
205	      if (it->name() == "ConfigureDistributedTPU") {
206	        nodes->erase(it);
207	        break;
208	      }
209	    }
210	
211	    auto session_options =
212	        tensorflow::tfrt_stub::CreateDefaultSessionOptions(options);
213	    session_options.config.mutable_experimental()
214	        ->set_optimize_for_static_graph(
215	            options_.config.experimental().optimize_for_static_graph());
216	    session_options.config.mutable_experimental()
217	        ->set_disable_optimize_for_static_graph(
218	            options_.config.experimental().disable_optimize_for_static_graph());
219	    LOG_FIRST_N(INFO, 10) << "SessionOptions: "
220	                          << session_options.config.DebugString();
221	
222	    // Creating the fallback_state using the original function def library
223	    // without applying placer or grappler, it is OK for now because it's only
224	    // used for captured functions in certain tf.data ops
225	    const auto& fdef_lib = graph.library();
226	    TF_ASSIGN_OR_RETURN(
227	        auto fallback_state,
228	        tensorflow::tfrt_stub::FallbackState::CreateWithDeviceMgr(
229	            session_options, fdef_lib, device_manager_.get()));
230	
231	    auto kernel_registry = std::make_unique<mlrt::KernelRegistry>();
232	    // Register infra and standard math kernels
233	    tensorflow::tf_mlrt::RegisterTfMlrtKernels(*kernel_registry);
234	    tensorflow::tf_mlrt::RegisterTfMlrtBatchKernels(*kernel_registry);
235	
236	    auto resource_context = std::make_unique<tfrt::ResourceContext>();
237	    tfrt_stub::ModelRuntimeContext model_context(
238	        &options, /*export_dir=*/"unknown_export_dir", resource_context.get());
239	    // TODO(b/334641254): Offer a Session option that prunes the graph_def.
240	    model_context.set_graph_def(&graph);
241	    model_context.set_device_mgr(&fallback_state->device_manager());
242	    if (backend_compiler_) {
243	      model_context.set_is_local_session(false);
244	    }
245	    TF_RETURN_IF_ERROR(options.runtime->CreateRuntimeResources(model_context));
246	
247	    // Run post-partition graph optimization passes which have been registered
248	    // in `OptimizationPassRegistry::Global()`.
249	    GraphOptimizationPassOptions optimization_options;
250	    optimization_options.session_options = &options_;
251	    FunctionLibraryDefinition flib_def = fallback_state->func_lib_def();
252	    optimization_options.flib_def = &flib_def;
253	    std::unordered_map<std::string, std::unique_ptr<Graph>> partition_graphs;
254	    auto initial_graph =
255	        std::make_unique<tensorflow::Graph>(tensorflow::OpRegistry::Global());
256	    tensorflow::GraphConstructorOptions opts;
257	    opts.allow_internal_ops = true;
258	    TF_RETURN_IF_ERROR(
259	        tensorflow::ConvertGraphDefToGraph(opts, graph, initial_graph.get()));
260	    partition_graphs["graph"] = std::move(initial_graph);
261	    optimization_options.partition_graphs = &partition_graphs;
262	    OptimizationPassRegistry::Global()->LogAllGroupings(1);
263	    TF_RETURN_IF_ERROR(OptimizationPassRegistry::Global()->RunGrouping(
264	        OptimizationPassRegistry::POST_PARTITIONING, optimization_options));
265	
266	    // `GraphExecutor::Create()` will preprocess the graph (e.g., apply
267	    // Placer to the top level graph). `kernel_registry` is required only for
268	    // synchronous execution right now.
269	    LOG_FIRST_N(INFO, 10) << "GraphExecutionOptions: " << options;
270	    TF_ASSIGN_OR_RETURN(
271	        graph_executor_,
272	        tensorflow::tfrt_stub::GraphExecutor::Create(
273	            options, std::move(fallback_state), std::move(resource_context),
274	            std::move(graph), std::move(kernel_registry)));
275	
276	    session_state_ = SessionState::kCreated;
277	    return absl::OkStatus();
278	  }
