414	  /// \brief Invokes the subgraph named by `handle` with the given options and
415	  /// input tensors.
416	  ///
417	  /// The order of tensors in `feed_tensors` must and `fetch_tensors` will
418	  /// match the order of names in `CallableOptions::feed()` and
419	  /// `CallableOptions::fetch()` when this subgraph was created.
420	  /// NOTE: This API is still experimental and may change.
421	  absl::Status RunCallable(CallableHandle handle,
422	                           const std::vector<Tensor>& feed_tensors,
423	                           std::vector<Tensor>* fetch_tensors,
424	                           RunMetadata* run_metadata) override {
425	    return RunCallable(handle, feed_tensors, fetch_tensors, run_metadata, {});
426	  }
