590	std::unique_ptr<tensorflow::tfrt_stub::WorkQueueInterface>
591	CreateRunHandlerWorkQueue(const TfrtThreadpoolOptions& session_options) {
592	  // Use half of the main threads as the default value for the
593	  // number of complementary threads. The complimentary threads are only used
594	  // for help to process intra ops if the main threads are blocked.
595	  int num_complementary_threads =
596	      std::max(1, session_options.num_main_threads / 2);
597	
598	  tfrt::tf::RunHandlerThreadWorkQueue::Options options;
599	  options.num_main_threads =
600	      session_options.num_main_threads;  // NOMUTANTS--performance tuning
601	  options.num_complementary_threads = num_complementary_threads;
602	  options.init_timeout_ms =
603	      absl::ToInt64Milliseconds(session_options.init_timeout);
604	  options.max_concurrent_handler =
605	      session_options.max_concurrent_handler;  // NOMUTANTS--performance tuning
606	  options.num_sub_thread_pool =
607	      session_options.num_sub_thread_pool;  // NOMUTANTS--performance tuning
608	
609	  // The number of threads in each sub thread pool is not specified,
610	  // we evenly distributed the number of threads to each thread pool by
611	  // default.
612	  std::vector<int> num_threads;
613	  const int num_threads_per_pool =
614	      options.num_main_threads / options.num_sub_thread_pool;
615	
616	  num_threads.resize(options.num_sub_thread_pool - 1, num_threads_per_pool);
617	  num_threads.push_back(options.num_main_threads -
618	                        (options.num_sub_thread_pool - 1) *
619	                            num_threads_per_pool);
620	  options.num_threads_in_sub_thread_pool = num_threads;
621	  options.sub_thread_request_percentage = {1.0};
622	
623	  options.use_adaptive_waiting_time = true;
624	
625	  LOG_FIRST_N(INFO, 10) << "RunHandlerThreadWorkQueue Options: " << options;
626	  return std::make_unique<tfrt::tf::RunHandlerThreadWorkQueue>(options);
627	}
