693	    ThreadPoolWithNumThreads(int num_thread,
694	                             std::unique_ptr<thread::ThreadPool> thread_pool)
695	        : num_threads_(num_thread),
696	          thread_pool_(std::move(thread_pool)),
697	          thread_pool_interface_wrapper_(
698	              ABSL_DIE_IF_NULL(thread_pool_)->AsEigenThreadPool()) {}
